+                    if (op instanceof TryOp tryOp && requiresNormalization.test(tryOp)) {
+                        block.context().mapValue(tryOp.result(), normalizer.apply(tryOp, block));
+                    } else {
+                        block.add(op);
+                    }
+                    return block;
+                });
